before_function:
public void onApplicationEvent(JobTaskFailAlarmEvent event) {
    if (!queue.offer(event.getJobTaskBatchId())) {
        SnailJobLog.LOCAL.warn("JOB任务执行失败告警队列已满");
    }
}

after_function:
public void doOnApplicationEvent(JobTaskFailAlarmEvent event) {
    if (!queue.offer(event.getJobTaskBatchId())) {
        SnailJobLog.LOCAL.warn("JOB任务执行失败告警队列已满");
    }
}
